"""Write tests/generated_layout.rs: compile-time layout/constant checks against clang's aarch64 values."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRATCH = os.path.join(ROOT, "target", "libnx-gen")  # clang outputs (see regen.sh)
g = json.load(open(os.path.join(SCRATCH, "gen_out.json")))
macros = json.load(open(os.path.join(SCRATCH, "macros.json")))
unions = set(g["unions"])
out = ["//! Generated by tools/gen_tests.py: checks the Rust layouts and constants against clang's",
       "//! AArch64 record layouts and evaluated constants. Do not edit.",
       "#![allow(non_snake_case, unused_unsafe, deprecated)]",
       "use core::mem::{align_of, offset_of, size_of};",
       "use libnx::bsd::*;", "use libnx::newlib::*;", "use libnx::*;", "",
       "#[allow(dead_code)]", "const _: () = {"]
union_names = set()
paths = {}
for name, key, rows, size, align, mod in g["records"]:
    paths[name] = f"libnx::{mod}::{name}"
    name = paths[name]
    out.append(f"    assert!(size_of::<{name}>() == {size});")
    out.append(f"    assert!(align_of::<{name}>() == {align});")
    is_union = key.startswith("union:") or name in unions and all(r[1] == 0 for r in rows)
    for fname, off, kind in rows:
        if key.startswith("union:"):
            continue
        out.append(f"    assert!(offset_of!({name}, {fname}) == {off});")
seen = set()
for nm, v in g["enum_consts"]:
    if nm in seen:
        continue
    seen.add(nm)
    out.append(f"    assert!({nm} as i128 == {v});")
for rel, items in macros.items():
    for nm, ty, val, _ in items:
        if nm in seen or ty in ("&CStr", "f32", "f64", "bool"):
            continue
        seen.add(nm)
        v = int(val, 16) if val.lstrip("-").startswith("0x") and not val.startswith("-") else (-int(val[1:], 16) if val.startswith("-0x") else int(val))
        out.append(f"    assert!({nm} as i128 == {v});")
out.append("};")
out.append("")
out.append("/// Sets each bitfield to all-ones on a zeroed struct and compares the bytes with clang's bit offsets.")
out.append("#[test]")
out.append("fn bitfields_match_clang_layout() {")
for rec, f, bitoff, width, vt, size in g["bitfields"]:
    rec = paths[rec]
    val = "true" if vt == "bool" else ("-1" if vt.startswith(("i", "s", "c_int", "c_schar", "c_short", "c_long")) and not vt.startswith("i128") else f"{vt}::MAX")
    exp = [0] * size
    for b in range(bitoff, bitoff + width):
        exp[b // 8] |= 1 << (b % 8)
    nz = [(i, x) for i, x in enumerate(exp) if x]
    out.append(f"    {{ let mut s = {rec}::default(); s.set_{f}({val} as _); let b = unsafe {{ core::slice::from_raw_parts((&raw const s).cast::<u8>(), {size}) }};")
    out.append(f"      let mut e = [0u8; {size}]; " + " ".join(f"e[{i}] = {x};" for i, x in nz) + f" assert_eq!(b, &e[..], \"{rec}.{f}\");")
    signed = val == "-1"
    expect = "1" if vt == "bool" else ("-1" if signed else str((1 << width) - 1))
    out.append(f"      assert_eq!(s.{f}() as i128, {expect}, \"{rec}.{f} roundtrip\"); }}")
out.append("}")
open(os.path.join(ROOT, "src", "tests", "generated_layout.rs"), "w").write("\n".join(out) + "\n")
print(len(out), "lines")
